type": "article", "cited_by_count": 0, "open_access": {"is_oa": true, "oa_status": "hybrid", "oa_url": "https://onlinelibrary.wiley.com/doi/pdfdirect/10.1002/hrm.70099", "any_repository_has_fulltext": true}, "primary_location": {"id": "doi:10.1002/hrm.70099", "doi": "https://doi.org/10.1002/hrm.70099", "is_oa": true, "landing_page_url": "https://doi.org/10.1002/hrm.70099", "pdf_url": "https://onlinelibrary.wiley.com/doi/pdfdirect/10.1002/hrm.70099", "source": {"id": "https://openalex.org/S134094273", "display_name": "Human Resource Management", "issn_l": "0090-4848", "issn": ["0090-4848", "1099-050X"], "is_oa": false, "is_in_doaj": false, "is_core": true, "listed_in": ["abdc-a-star", "anvur-class-a", "anvur-scientific", "cwts-core", "erih-plus", "fnege-1", "ft50", "jufo-3", "ki-jl-1", "norway-2", "poland-100", "russia-white-list-1", "vabb-shw"], "host_organization": "https://openalex.org/P4310320595", "host_organization_name": "Wiley", "host_organization_lineage": ["https://openalex.org/P4310320595"], "host_organization_lineage_names": ["Wiley"], "type": "journal"}, "license": "cc-by", "license_id": "https://openalex.org/licenses/cc-by", "version": "publishedVersion", "is_accepted": true, "is_published": true, "raw_source_name": "Human Resource Management", "raw_type": "journal-article"}, "abstract": "ABSTRACT The core principle in strategic human resource management (SHRM) holds that organizations gain competitive advantage from HR systems with practices that work well together (horizontal alignment) and that support overall strategy (vertical alignment). This paper develops a theory explaining how artificial intelligence integration, a tool intended to improve alignment, can unintentionally cause alignment breakdown. Drawing on SHRM theory and the process‐based model of HRM system strength, we build four propositions. We argue that AI's operational requirements weaken horizontal alignment by creating logic conflicts within HR systems, cause employee skill development to drift from strategic needs, cause employees to default to metric‐aligned behaviors, and diminish workforce value as a competitive resource. We synthesize these dynamics in a framework of four organizational states, Strategic Synergy, Contested Alignment, Strategic Fragmentation, and Algorithmic Capture that characterize firms at different stages of AI‐driven misalignment. This paper contributes a process‐based theory explaining organizational risks of AI adoption in management systems."}]", "excerpt_truncated": true, "source_sha256": "d7fdd2a1a3a2c30e704fee0886a8047faf89767cf208115a99495eb9c7683b33", "verification_required": true, "topic_domain": "creator_objective_critique", "evidence_role": "discovery", "host_tier": "discovery", "source_identity": null, "persistent_identifiers": ["doi:10.1007/s11229-023-04367-0", "doi:10.1007/s11229-023-04367-0.pdf", "doi:10.1002/hrm.70099", "openalex:W4388198642"], "source_candidates": ["https://doi.org/10.1007/s11229-023-04367-0", "https://link.springer.com/content/pdf/10.1007/s11229-023-04367-0.pdf", "https://onlinelibrary.wiley.com/doi/pdfdirect/10.1002/hrm.70099", "https://doi.org/10.1002/hrm.70099"], "source_candidate_identities": {}}
